module traffic_light (
    input clk,
    input reset,
    input ped,
    output reg [1:0] light,
    output reg walk
);

    reg [2:0] state;
    reg [2:0] next_state;
    reg [2:0] cnt;

    always @(posedge clk) begin
        if (reset) begin
            state <= 3'd0;
            cnt <= 3'd0;
            light <= 2'b00;
            walk <= 1'b1;
        end else begin
            if (state == 3'd0) begin
                next_state = 3'd0;
                cnt <= 3'd3;
            end else if (state == 3'd1) begin
                if (cnt == 3'd0) begin
                    next_state = 3'd2;
                    cnt <= 3'd4;
                end else begin
                    next_state = 3'd1;
                    cnt <= cnt - 1;
                end
            end else if (state == 3'd2) begin
                if (cnt == 3'd0) begin
                    next_state = 3'd3;
                    cnt <= 3'd2;
                end else begin
                    next_state = 3'd2;
                    cnt <= cnt - 1;
                end
            end else if (state == 3'd3) begin
                if (cnt == 3'd0) begin
                    next_state = 3'd0;
                    cnt <= 3'd3;
                end else begin
                    next_state = 3'd3;
                    cnt <= cnt - 1;
                end
            end else if (state == 3'd4) begin
                if (cnt == 3'd0) begin
                    next_state = 3'd0;
                    cnt <= 3'd3;
                end else begin
                    next_state = 3'd4;
                    cnt <= cnt - 1;
                end
            end
            state <= next_state;
            cnt <= cnt;
        end
    end

    always @(posedge clk) begin
        if (reset) begin
            light <= 2'b00;
            walk <= 1'b1;
        end else begin
            case (state)
                3'd0: begin
                    light <= 2'b00;
                    walk <= 1'b1;
                end
                3'd1: begin
                    light <= 2'b01;
                    walk <= 1'b0;
                end
                3'd2: begin
                    light <= 2'b10;
                    walk <= 1'b0;
                end
                3'd3: begin
                    light <= 2'b00;
                    walk <= 1'b1;
                end
                3'd4: begin
                    light <= 2'b10;
                    walk <= 1'b0;
                end
            endcase
        end
    end

endmodule

